using System;
using System.Collections.Generic;

namespace RobotMissionMS.DataAccess.Entities;

/// <summary>
/// Robot and both locations must belong to the same Zone as the mission.
/// </summary>
public partial class Mission
{
    public Guid Id { get; set; }

    public string MissionCode { get; set; } = null!;

    public Guid MissionTypeId { get; set; }

    public Guid ZoneId { get; set; }

    public Guid? BatchId { get; set; }

    /// <summary>
    /// set for missions generated by a recurring schedule
    /// </summary>
    public Guid? ScheduleId { get; set; }

    /// <summary>
    /// schedule run time this mission was generated for
    /// </summary>
    public DateTime? ScheduledFor { get; set; }

    /// <summary>
    /// required unless ScheduleId is set
    /// </summary>
    public Guid? FromLocationId { get; set; }

    /// <summary>
    /// required unless ScheduleId is set
    /// </summary>
    public Guid? ToLocationId { get; set; }

    /// <summary>
    /// same code for missions split from one request / import row
    /// </summary>
    public string? RequestCode { get; set; }

    /// <summary>
    /// one item type per mission; required unless ScheduleId is set
    /// </summary>
    public Guid? ItemId { get; set; }

    /// <summary>
    /// 1..Items.MaxQtyPerSlot (checked in backend)
    /// </summary>
    public int? Quantity { get; set; }

    public string? Note { get; set; }

    public DateTime? DeadlineAt { get; set; }

    /// <summary>
    /// current trip; the robot is on the trip
    /// </summary>
    public Guid? TripId { get; set; }

    /// <summary>
    /// slot on the robot (one mission per slot)
    /// </summary>
    public int? SlotNo { get; set; }

    public string? FailNote { get; set; }

    public Guid? CreatedByUserId { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime? PickedUpAt { get; set; }

    public DateTime? StartedAt { get; set; }

    public DateTime? CompletedAt { get; set; }

    public virtual ICollection<Alert> Alerts { get; set; } = new List<Alert>();

    public virtual Batch? Batch { get; set; }

    public virtual User? CreatedByUser { get; set; }

    public virtual Location? FromLocation { get; set; }

    public virtual Item? Item { get; set; }

    public virtual ICollection<MissionStatusHistory> MissionStatusHistories { get; set; } = new List<MissionStatusHistory>();

    public virtual MissionType MissionType { get; set; } = null!;

    public virtual MissionSchedule? Schedule { get; set; }

    public virtual Location? ToLocation { get; set; }

    public virtual Trip? Trip { get; set; }

    public virtual Zone Zone { get; set; } = null!;
}
